/bin/bash -lc "mkdir -p lib
cat <<'EOF' > lib/analytics.ts
export type PageViewEvent = {
  path: string;
  userAgent: string;
  referer: string;
  timestamp: string;
};

const ANALYTICS_ENDPOINT = process.env.ANALYTICS_ENDPOINT;

export async function logPageView(event: PageViewEvent): Promise<void> {
  if ("'!ANALYTICS_ENDPOINT) {
    console.info('"'[analytics] Page view', event);
    return;
  }

  try {
    const response = await fetch(ANALYTICS_ENDPOINT, {
      method: 'POST',
      headers: {
        'content-type': 'application/json'
      },
      body: JSON.stringify(event),
      keepalive: true
    });

    if ("'!response.ok) {
      console.warn('"'[analytics] Failed to log page view', {
        status: response.status,
        statusText: response.statusText
      });
    }
  } catch (error) {
    console.warn('[analytics] Failed to log page view', error);
  }
}
EOF"

